-- openpay.id initial schema.
--
-- All identifiers are TEXT (UUID/opaque strings generated by the application)
-- rather than the uuid type, so the engine can use prefixed ids such as
-- "trx_..." without a lossy cast.

CREATE TABLE IF NOT EXISTS merchants (
    id             TEXT PRIMARY KEY,
    name           TEXT        NOT NULL,
    api_key_hash   TEXT        NOT NULL UNIQUE,
    api_key_prefix TEXT        NOT NULL DEFAULT '',
    callback_url   TEXT        NOT NULL DEFAULT '',
    webhook_secret TEXT        NOT NULL DEFAULT '',
    routing        JSONB       NOT NULL DEFAULT '{}'::jsonb,
    status         TEXT        NOT NULL DEFAULT 'active',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS transactions (
    id                 TEXT PRIMARY KEY,
    merchant_id        TEXT        NOT NULL REFERENCES merchants (id),
    reference_id       TEXT        NOT NULL,
    provider_name      TEXT        NOT NULL,
    provider_reference TEXT        NOT NULL DEFAULT '',
    method             TEXT        NOT NULL,
    channel            TEXT        NOT NULL DEFAULT '',
    amount             BIGINT      NOT NULL,
    currency           TEXT        NOT NULL DEFAULT 'IDR',
    status             TEXT        NOT NULL,
    payment_code       TEXT        NOT NULL DEFAULT '',
    actions            JSONB,
    customer           JSONB,
    items              JSONB,
    description        TEXT        NOT NULL DEFAULT '',
    metadata           JSONB,
    failure_reason     TEXT        NOT NULL DEFAULT '',
    expires_at         TIMESTAMPTZ,
    paid_at            TIMESTAMPTZ,
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- Idempotency: one payment per merchant reference.
    CONSTRAINT transactions_merchant_reference_key UNIQUE (merchant_id, reference_id)
);

-- One transaction per gateway reference (empty references are ignored).
CREATE UNIQUE INDEX IF NOT EXISTS transactions_provider_reference_key
    ON transactions (provider_name, provider_reference)
    WHERE provider_reference <> '';

CREATE INDEX IF NOT EXISTS transactions_merchant_created_idx
    ON transactions (merchant_id, created_at DESC);

CREATE INDEX IF NOT EXISTS transactions_status_idx
    ON transactions (status);

CREATE TABLE IF NOT EXISTS webhook_deliveries (
    id              TEXT PRIMARY KEY,
    transaction_id  TEXT        NOT NULL,
    merchant_id     TEXT        NOT NULL,
    event_type      TEXT        NOT NULL,
    url             TEXT        NOT NULL,
    payload         JSONB,
    status          TEXT        NOT NULL DEFAULT 'pending',
    attempts        INTEGER     NOT NULL DEFAULT 0,
    max_attempts    INTEGER     NOT NULL DEFAULT 6,
    last_error      TEXT        NOT NULL DEFAULT '',
    last_attempt_at TIMESTAMPTZ,
    next_attempt_at TIMESTAMPTZ,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS webhook_deliveries_pending_idx
    ON webhook_deliveries (status, next_attempt_at);
